import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict with side, price, qty, ts, active
    buy_heap = []  # (-price, ts, id) max-heap by price then earliest time
    sell_heap = []  # (price, ts, id) min-heap by price then earliest time
    ts_counter = 0

    def clean(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(heap)
            else:
                break

    for order in orders:
        ts_counter += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        price = None
        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
        else:
            continue

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
            while remaining > 0:
                clean(opp_heap)
                if not opp_heap:
                    break
                p, t, sid = opp_heap[0]
                so = book[sid]
                if typ != 'market' and price is not None and p > price:
                    break
                trade_qty = min(remaining, so['qty'])
                trades.append([oid, sid, p, trade_qty])
                remaining -= trade_qty
                so['qty'] -= trade_qty
                if so['qty'] == 0:
                    so['active'] = False
                    heapq.heappop(opp_heap)
                clean(opp_heap)
        else:
            opp_heap = buy_heap
            while remaining > 0:
                clean(opp_heap)
                if not opp_heap:
                    break
                negp, t, bid = opp_heap[0]
                p = -negp
                bo = book[bid]
                if typ != 'market' and price is not None and p < price:
                    break
                trade_qty = min(remaining, bo['qty'])
                trades.append([bid, oid, p, trade_qty])
                remaining -= trade_qty
                bo['qty'] -= trade_qty
                if bo['qty'] == 0:
                    bo['active'] = False
                    heapq.heappop(opp_heap)
                clean(opp_heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'ts': ts_counter, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, ts_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, ts_counter, oid))

    return trades

